package com.artforyou.store.entity;
import jakarta.persistence.*;
@Entity @Table(name="collections") public class CollectionEntity { @Id private String slug; @Column(nullable=false) private String title; @Column(name="sort_order") private int sortOrder; @Column(columnDefinition="text") private String description=""; @Column(name="image_path") private String imagePath=""; @Column(columnDefinition="boolean default true") private boolean active=true; public String getSlug(){return slug;} public String getTitle(){return title;} public int getSortOrder(){return sortOrder;} public String getImagePath(){return imagePath;} public String getDescription(){return description;} public boolean isActive(){return active;} public void setSlug(String v){slug=v;} public void setTitle(String v){title=v;} public void setSortOrder(int v){sortOrder=v;} public void setImagePath(String v){imagePath=v;} public void setDescription(String v){description=v;} public void setActive(boolean v){active=v;} }
